documents.content:
{
  "category": "as_built_requirements",
  "description": "Underlag för relationshandlingar — requirements on the basis for as-built documents. Source: AMA VVS & Kyla 19.",
  "source": "AMA VVS & Kyla 19",
  "requirements": [
    { "sv": "De ska överensstämma med verkligt utförande och funktion.", "en": "They must correspond to the actual execution and function." },
    { "sv": "De ska vara undertecknade av entreprenören.", "en": "They must be signed by the contractor." },
    { "sv": "De ska bestå av kopior av de handlingar som legat till grund för utförande av entreprenaden och på vilka förts in avvikelser som gjorts under arbetets gång, med skiss om så behövs.", "en": "They must consist of copies of the documents that formed the basis for executing the contract, with any deviations made during the work entered on them, including a sketch where needed." },
    { "sv": "De ska innehålla lägesuppgifter för sådana utrustningar, enheter, apparater och dylikt vars definitiva placering inte redovisats i handling.", "en": "They must contain position data for equipment, units, apparatus and similar whose final placement was not shown in the documents." }
  ],
  "additional_rules": [
    { "en": "Dimensions and other measurement data must be drawn in and stated so clearly and completely that they can serve as a basis for relationshandlingar." },
    { "en": "A special set of drawings (särskild ritningsomgång) must be kept on site, into which the basis for relationsritningar is entered progressively. The drawing basis must be made in a clear and unambiguous way and with the same symbols that occur elsewhere on the drawings. Text that is a clarifying comment should be circled so that it is not misunderstood." }
  ],
  "coordinated_as_builts": {
    "title_sv": "Samordnade relationshandlingar",
    "title_en": "Coordinated as-built documents",
    "text_en": "For changes and rebuilds the contractor most often delivers documentation only of the new work installed. As-built drawings for a building therefore usually consist partly of drawings from the time of the original construction and partly of drawings from later changes and rebuilds. It is of great value to a property owner to have coordinated relationshandlingar for the VVS installations."
  },
  "example_markup_reading": {
    "description_en": "Example of a marked-up basis for relationsritningar: a hand-annotated ritning in which removed items are struck through and new items are written in. Typical annotations seen in such a markup include RA1 struck through, RV21-15 Kv=0,1 struck through and replaced by 2xAV21-28, SV21-15 added, and a group of pipes labelled VVC1 15, VV1 28, KV1 28, S1 110.",
    "takeoff_implication": "As-built markup is the ground truth for befintlig installation. Struck-through items are removals; hand-written items are additions. Both need to be captured separately in mängdavtagning of a rebuild."
  }
}

{
  "category": "control_device",
  "description": "Ritningssymboler för styrventiler m m — control and actuator symbols. On older ritningar the ställdon (actuator) symbol was a square rather than a circle.",
  "entries": [
    { "code": "RC", "term_sv": "Reglercentral",                "term_en": "Control unit / controller",              "symbol_description": "Small square with dashed lines rising from it." },
    { "code": "ST", "term_sv": "Handställdon",                 "term_en": "Manual actuator",                        "symbol_description": "T shape on the valve stem." },
    { "code": "ST", "term_sv": "Övriga ställdon, grundsymbol", "term_en": "Other actuators, base symbol",           "symbol_description": "Circle on the valve stem.", "older_symbol": "Square on the valve stem." },
    { "code": "SV", "term_sv": "Styrventil, manuell",          "term_en": "Control valve, manual",                  "symbol_description": "Bowtie with a plain stem." },
    { "code": "SV", "term_sv": "Styrventil med automatiskt ställdon", "term_en": "Control valve with automatic actuator", "symbol_description": "Bowtie with a circle (actuator) on the stem.", "older_symbol": "Bowtie with a square on the stem." }
  ]
}

{
  "category": "document_change_handling",
  "description": "Ändring av handlingar — changing a förfrågningsunderlag or a bygghandling should be done consistently and clearly, so that there is no uncertainty about what has been changed.",
  "drawing_change_markers": {
    "title_sv": "Ändring av ritning",
    "title_en": "Change to a drawing",
    "intro_en": "That a drawing has been changed is stated:",
    "places": [
      { "sv": "på ritningen vid ändringsställe (i \"moln\")", "en": "on the drawing at the point of change (in a revision 'cloud')" },
      { "sv": "på ritningens namnruta i ändringstabell", "en": "in the revision table of the drawing's title block" },
      { "sv": "på ritningens namnruta i plats för ändringsbeteckning", "en": "in the title block, in the space for the revision designation" },
      { "sv": "i handlingsförteckning/ritningsförteckning", "en": "in the document list / drawing list" },
      { "sv": "i KFU/PM", "en": "in the KFU or the PM" }
    ]
  },
  "text_document_change_markers": {
    "title_sv": "Ändring av texthandling",
    "title_en": "Change to a text document",
    "intro_en": "That a beskrivning (text document) has been changed is stated:",
    "places": [
      { "sv": "i texthandlingen vid ändringsstället", "en": "in the text document at the point of change" },
      { "sv": "på texthandlingens samtliga sidor", "en": "on all pages of the text document" },
      { "sv": "på texthandlingens titelsida", "en": "on the title page of the text document" },
      { "sv": "i KFU/PM", "en": "in the KFU or the PM" }
    ]
  },
  "accompanying_documents": [
    { "status": "Förfrågningsunderlag", "document": "KFU (kompletterande förfrågningsunderlag)", "note_en": "Normally attached when tender documents are changed." },
    { "status": "Bygghandling", "document": "Ändrings-PM", "note_en": "Attached when a construction document is changed. KFU and PM are numbered in the same sequence." }
  ],
  "takeoff_implication": "A takeoff pipeline must version drawings by ändringsbeteckning (A, B, C, D ...) and re-run affected quantities when a KFU or Ändrings-PM is issued. Revision clouds mark the regions to re-measure."
}

{
  "category": "document_rule",
  "description": "General rules on ritningar och beskrivningar (drawings and specifications) and their precedence, plus CAD/BIM digital information handling.",
  "entries": [
    {
      "id": "basis",
      "title_en": "What the technical execution rests on",
      "text_en": "Ritningar and beskrivningar are the basis for the technical execution of most larger construction projects. Ritningar are built on standards and standardised drawing symbols. Tekniska beskrivningar most often link to AMA."
    },
    {
      "id": "complete_set",
      "title_en": "What a complete set of bygghandlingar usually contains",
      "items_sv": ["Handlingsförteckning", "Ritningar", "Beskrivningar", "CAD eller Revit ritningar (3D modeller)"],
      "items_en": ["Document list", "Drawings", "Specifications", "CAD or Revit drawings (3D models)"]
    },
    {
      "id": "complementary",
      "title_en": "Drawings and specifications complement each other",
      "text_en": "In contracts it normally applies that ritningar and beskrivningar complement each other. The prescribed execution does not need to be described in both the ritning and the beskrivning. It is therefore important that the fitter (montören) on site always has access to the beskrivning."
    },
    {
      "id": "precedence_drawing_vs_spec",
      "title_en": "Precedence between drawing and specification",
      "text_en": "In the event of a conflict between ritning and beskrivning, the beskrivning takes precedence over the ritning (in an utförandeentreprenad, i.e. a design-bid-build contract).",
      "takeoff_implication": "When automated reading of a ritning conflicts with the beskrivning, the beskrivning wins. Flag the conflict rather than silently trusting the drawing."
    },
    {
      "id": "precedence_ama",
      "title_en": "Precedence involving AMA",
      "text_en": "In addition to the text in the beskrivning, the text in AMA applies. Because a code and its associated heading from AMA appear in the beskrivning, both the text under that heading in AMA and the text in superordinate headings are invoked, according to the so-called pyramidregeln (pyramid rule). If there is a conflict between AMA's text and the text of the beskrivning, the beskrivning applies."
    },
    {
      "id": "other_site_documents",
      "title_en": "Other documents that apply on site",
      "text_en": "There are several other documents to take into account on the construction site, for example environmental and work-environment rules and the manufacturers' installation instructions (monteringsanvisningar)."
    },
    {
      "id": "as_built_duty",
      "title_en": "Recording changes during construction",
      "text_en": "An important task on site is to continuously enter changes made during construction on a separate set of drawings, as the basis for relationsritningar."
    },
    {
      "id": "symbol_standards",
      "title_en": "Symbol standards and praxis",
      "text_en": "Ritningar and beskrivningar can be produced according to Bygghandlingar 90. A standard for drawing symbols on VVS-ritningar is SIS 32260, which differs somewhat from the European standard. The industry also has praxis that can differ considerably from case to case, depending on the consultants' and clients' own routines."
    }
  ],
  "bim_section": {
    "title_sv": "CAD och digital informationshantering",
    "title_en": "CAD and digital information handling",
    "paragraphs_en": [
      "BIM, Byggnads Informations Modellering (Building Information Modelling), is systematic digital information handling in construction projects. Designers draw the building and its installations in 3D models. These contain objects with properties. For a pump, for example, there is data on weight, dimensions, pump curve, electrical data, installation instructions, operation and maintenance instructions and byggvarudeklaration (construction product declaration). The information is accessible to everyone concerned.",
      "In the design stage you can walk around the model - as in a computer game or with VR technology - and check buildability and coordination between the different technical disciplines. Dimensioning, for example pressure drop calculation for the heating system, can be carried out.",
      "From the 3D models information can be exported to systems for kalkyl (estimating), setting out, planning, purchasing, logistics, facility management, operation and maintenance. Drawings, dimensions and other data are easily produced from the model. Extracts to tablets make the work easier for the fitter, the inspector and operating staff.",
      "In many projects the model is used today together with 'produktionsprogram' instead of drawings as an aid for fitters in their work. There they can view the model in both 2D and 3D, measure, carry out self-checks, report deviations and so on. This gives better documentation, higher quality and often faster handling of questions.",
      "BIP, Building Information Properties, and the classification system CoClass, with systematic designations and properties, make it possible for the information to be reused in several steps. BIP QTO makes it possible to obtain quantities sorted and summed for other systems.",
      "In the facility management stage, operating staff can extract information from the model, for example a spare parts list for repair or replacement. The model can be used on tablets as support in work orders and when reporting back on measures taken. Ahead of a rebuild, all information about the existing installations is available.",
      "All of this requires that the information is entered at the manufacturer stage, during design and in the relationshandlingar."
    ],
    "references": ["www.bipkoder.se", "www.in.se (Installatörsföretagen)"],
    "information_chain_example": "The layered illustration in the source shows the chain from product and monteringsanvisning up through 3D-ritning, haltagningsritning, mängdförteckning, planritning, BIM and Säker Vatten, with the pipe label example 'KV, KALLVATTEN / KOPPAR DIM 35 / ALUCOAT 40MM'."
  }
}

{
  "category": "dou_instructions",
  "description": "Underlag för drift- och underhållsinstruktioner — basis for operation and maintenance (DoU) instructions.",
  "standard": {
    "publisher": "Svensk Byggtjänst",
    "title_sv": "Drift- och underhållsinstruktioner & annan dokumentation i entreprenader",
    "year": 2023,
    "scope_en": "An industry standard that provides templates both for operation and maintenance instructions and for the basis for them."
  },
  "legal_basis_en": "The industry standard rests on the fact that both building legislation and work environment legislation require buildings and their installations to have instructions. Responsibility for these existing lies with the property owner (fastighetsägaren). The instructions can take the form of a database or, traditionally, a binder.",
  "also_included_en": "The industry standard also contains templates for contract documentation and checklists for environment, work environment, fire inspection and maintenance inspection, and inspection records for pressure and tightness testing, adjustment of circulation flows (injustering av cirkulationsflöden) and sound pressure level.",
  "page_header_requirements": [
    { "sv": "projektnamn", "en": "project name" },
    { "sv": "datum", "en": "date" },
    { "sv": "revideringsdatum", "en": "revision date" },
    { "sv": "numrering som bör anges med kapitelnummer följt av löpnummer", "en": "numbering, which should be stated as chapter number followed by sequential number" }
  ],
  "template_structure": {
    "template_name": "Mall DoU 3 (AB Svensk Byggtjänst) - Underlag för DoU-instruktion, rörinstallation",
    "front_page_fields": ["Fastighet", "Projekt", "Upprättad av", "Upprättad datum", "Reviderad datum"],
    "sections": [
      { "group_sv": "ORIENTERING", "group_en": "Orientation", "chapters": [
