        { "no": 6, "sv": "Rutiner", "en": "Routines" },
        { "no": 7, "sv": "Apparater, komponenter", "en": "Apparatus, components" },
        { "no": 8, "sv": "Spjäll, ventiler, armatur", "en": "Dampers, valves, fittings" }
      ]},
      { "group_sv": "DOKUMENT", "group_en": "Documents", "chapters": [
        { "no": 9,  "sv": "Protokoll", "en": "Records / test reports" },
        { "no": 10, "sv": "Rör, brunnar", "en": "Pipes, wells" },
        { "no": 11, "sv": "Pumpar, värmeväxlare", "en": "Pumps, heat exchangers" },
        { "no": 12, "sv": "Värmare, kylare", "en": "Heaters, coolers" },
        { "no": 13, "sv": "Sanitetsinredning", "en": "Sanitary fixtures" },
        { "no": 14, "sv": "Sanitetsarmatur", "en": "Sanitary fittings" },
        { "no": 15, "sv": "Ventiler, mätdon", "en": "Valves, measuring devices" },
        { "no": 16, "sv": "Styr- och reglerdon", "en": "Control and regulating devices" },
        { "no": 17, "sv": "Övriga produkter", "en": "Other products" },
        { "no": 18, "sv": "Ritningar", "en": "Drawings" },
        { "no": 19, "sv": "Scheman", "en": "Schematics" },
        { "no": 20, "sv": "Övrigt", "en": "Other" }
      ]}
    ]
  }
}

{
  "category": "drawing_numbering",
  "description": "Ritningsnummer — a drawing number is split into three parts separated by hyphens: responsible party (ansvarig part), classification (klassifikation) and numbering (numrering). The classification part may be omitted.",
  "structure": {
    "parts": [
      { "part": "Ansvarig part", "part_en": "Responsible party / discipline", "example": "V", "note": "One letter (or two, e.g. SK)." },
      { "part": "Klassifikation - ritningens innehåll", "part_en": "Classification - drawing content", "example": "56", "note": "Two digits, huvudgrupp + delgrupp." },
      { "part": "Klassifikation - redovisningssätt", "part_en": "Classification - drawing category / presentation type", "example": "1", "note": "One digit." },
      { "part": "Numrering", "part_en": "Number", "example": "124", "note": "Location-coded or sequential." }
    ],
    "full_example": "V-56-1-124",
    "short_example": "V-124",
    "note_en": "Klassifikation can be omitted, so a drawing number may look like either V-124 or V-56-1-124."
  },
  "rules": [
    {
      "id": "typical_vvs_content_code",
      "rule_en": "For VVS-ritningar the content code is most often 50 or 57. Code 50 is used when several kinds of installation (e.g. heating, tappvatten and drainage) are shown on the same ritning, which makes it suitable for pipework installations (rörentreprenad)."
    },
    {
      "id": "coordinated_numbering",
      "rule_en": "Drawing numbering is generally coordinated between disciplines (A, E, V, etc.). In large projects numbers are built on a 'lägeskod' (location code) - e.g. the number 124 can mean building 1, building part 2, storey 4."
    },
    {
      "id": "sequential_numbering",
      "rule_en": "Drawings can also be numbered sequentially. All such numbers must contain the same number of digits and can be divided into number series, e.g. 101-199 or 201-299 for different groups of drawings."
    }
  ],
  "example_title_block_fields": [
    "Ändringstabell: BET / ANT / ÄNDRINGEN AVSER / DATUM / SIGN",
    "Handlingsstatus (e.g. PRELIMINÄR HANDLING, FÖRFRÅGNINGSUNDERLAG, BYGGHANDLING, RELATIONSHANDLING)",
    "Projekt / fastighet",
    "Discipline contact rows: A Arkitekt, K Konstruktör, V VVS-konsult, E El-konsult, L Landskap, Konsult (the responsible discipline is marked with a cross)",
    "Uppdrag nr",
    "Ritad/konstr av",
    "Handläggare",
    "Datum",
    "Ansvarig",
    "Type of work (e.g. NYBYGGNAD, OMBYGGNAD)",
    "Content (e.g. PLAN 1, DEL 2, VVS-INSTALLATIONER)",
    "Skala",
    "Nummer",
    "Bet (ändringsbeteckning)"
  ]
}

{
  "category": "pipe_marking_rule",
  "description": "How rörledningar (pipes) are labelled and drawn on VVS-ritningar. These rules govern how a takeoff engine should parse a pipe label and infer geometry.",
  "entries": [
    {
      "id": "label_format",
      "title": "Pipe label composition",
      "rule_en": "A pipe is labelled on the ritning with its systemtillhörighet (system designation) and its rördimension, e.g. KV-22, VS2-32, S1-160. The digit after the dash is the pipe dimension.",
      "rule_sv_source": "Rörledningar betecknas på ritningar med systemtillhörighet och rördimension.",
      "parse_pattern": "^(?<system>[A-ZÅÄÖ]{1,3}i?)(?<index>\\d*)-(?<dimension>\\d+)$",
      "examples": ["KV-28", "VV-15", "VVC-12", "KV1-35", "VS2-40", "KB2-50", "S1-160"]
    },
    {
      "id": "label_repetition",
      "title": "Repetition of the label",
      "rule_en": "The label is normally repeated for every individual pipe, except for circulating circuits (e.g. värmebärare or köldbärare), where one label refers to both the supply and the return pipe.",
      "rule_sv_source": "Beteckningen upprepas normalt för varje enskilt rör, utom för cirkulerande kretsar, exempelvis värme- eller köldbärare, där beteckningen syftar på både framlednings- och returrör."
    },
    {
      "id": "index_meaning",
      "title": "Meaning of the index digit",
      "rule_en": "An extra digit (index) may follow the system designation. Its meaning is defined by the ritning or the beskrivning. For KV, VV, VVC, S and D the index usually refers to the pipe material (rörmaterial), but can occasionally mean something else. For VS, KB and G the index can refer to the material but more often refers to the system: e.g. VS1 = a radiator group, VS2 = a ventilation group; KB1 = wet cooling, KB2 = dry cooling.",
      "rule_sv_source": "I vissa fall finns ytterligare en siffra, exempelvis: KV1-35, VS2-40, KB2-50. Detta index kan ha olika innebörd, vilket framgår av ritningar eller beskrivningar.",
      "notes": "Some designation systems are more complex and may also encode requirements on insulation and other properties. In that case there is usually a specific legend (särskild förklaring) on the ritning."
    },
    {
      "id": "properties_from_beskrivning",
      "title": "Material, jointing and insulation come from the beskrivning",
      "rule_en": "Rörmaterial, fogmetod (jointing method) and isolering (insulation) are not read from the pipe label. They are stated in the VVS-beskrivning.",
      "rule_sv_source": "Rörmaterial, fogmetod, isolering etc. framgår då av VVS-beskrivningen.",
      "takeoff_implication": "Quantity takeoff from a planritning alone yields length per system and dimension. Material and insulation must be joined in from the beskrivning before pricing."
    },
    {
      "id": "single_line_representation",
      "title": "Single-line representation on planritning",
      "rule_en": "Pipes on a planritning are shown as single lines (enkla linjer). Where pipes cross, the line is usually broken (avbrott på linjen).",
      "rule_sv_source": "Ledningar på planritningen redovisas som enkla linjer. Vid korsande rör görs ofta avbrott på linjen.",
      "takeoff_implication": "A gap in a line is a crossing indicator, not an end of pipe. Segmentation logic must reconnect across such breaks."
    },
    {
      "id": "section_convention",
      "title": "What a planritning section represents",
      "rule_en": "The line style on a ritning marks the position in front of or behind the theoretical section from which the view is drawn. A planritning normally shows a section at window level (fönsternivå) looking downwards, and the height of a pipe in the room is encoded in the line style.",
      "rule_sv_source": "Linjers utformning på en ritning markerar läget framför eller bakom det teoretiska snitt varifrån det avbildade betraktas. Planritningar redovisar normalt ett snitt i fönsternivå sett nedåt."
    }
  ]
}

{
  "category": "sensor_instrument",
  "description": "Beteckningar på givare och mätinstrument. Givare = sensor (G-prefix), Mätinstrument = measuring instrument (M-prefix). The second letter denotes the measured quantity. On a rörritning these are drawn as small symbols on a stem from the pipe: a cone for a givare, a circle with a pointer for a visande mätinstrument, a circle with an S for a skrivande (recording) instrument, a slash for a rörtermometer, and a bowtie with a circle for a styrventil med motor.",
  "entries": [
    { "sensor_code": "GF", "instrument_code": "MF", "quantity_sv": "Flöde",                   "quantity_en": "Flow" },
    { "sensor_code": "GL", "instrument_code": "ML", "quantity_sv": "Läge, nivå, vinkel, längd", "quantity_en": "Position, level, angle, length" },
    { "sensor_code": "GM", "instrument_code": "MM", "quantity_sv": "Fuktighet",               "quantity_en": "Humidity" },
    { "sensor_code": "GP", "instrument_code": "MP", "quantity_sv": "Tryck",                   "quantity_en": "Pressure" },
    { "sensor_code": "GS", "instrument_code": "MS", "quantity_sv": "Hastighet, varvtal",      "quantity_en": "Speed, rotational speed" },
    { "sensor_code": "GT", "instrument_code": "MT", "quantity_sv": "Temperatur",              "quantity_en": "Temperature" },
    { "sensor_code": "GX", "instrument_code": "MX", "quantity_sv": "Övrigt",                  "quantity_en": "Other" }
  ]
}

{
  "category": "side_contractor_equipment",
  "description": "Beteckningar som avser sidoentreprenörers installationer eller arbeten — designations for equipment installed under another (side) contract, mostly ventilation equipment.",
  "entries": [
    { "code": "LV",  "term_sv": "Luftvärmare (i ventilationsutrustning)",      "term_en": "Air heater (in ventilation equipment)" },
    { "code": "LK",  "term_sv": "Luftkylare (i ventilationsutrustning)",       "term_en": "Air cooler (in ventilation equipment)" },
    { "code": "SL",  "term_sv": "Slutapparat (i ventilationsutrustning)",      "term_en": "Terminal unit (in ventilation equipment)", "notes": "Code collision: SL also denotes Säkerhetsledning as a system designation." },
    { "code": "EB",  "term_sv": "Kylbaffel (utan tilluft)",                    "term_en": "Chilled beam (without supply air)" },
    { "code": "TB",  "term_sv": "Kylbaffel (med tilluft)",                     "term_en": "Chilled beam (with supply air)", "notes": "Code collision: TB also denotes Tillsynsbrunn among wells." },
    { "code": "LVE", "term_sv": "Lufteftervärmare (i ventilationsutrustning)", "term_en": "Air reheater (in ventilation equipment)" },
    { "code": "IL",  "term_sv": "Inspektionslucka",                            "term_en": "Inspection hatch / access panel" }
  ]
}

{
  "schema_version": 1,
