              "assemble.wall_gap": 60.606,
              "assemble.mark_merge": 4.545,
              "assemble.small_ring": 5.303,
              "associate.anchor": 12.121,
              "associate.landing": 4.545,
              "associate.twin_gap": 30.303,
              "bucket.tick_rel_min": 1.8
            },
            "signatures": [
              {
